-- Version-1 rubric for every skill, so verification sessions can reference one.
INSERT INTO rubric_versions (skill_id, version_no, dimensions, levels)
SELECT s.id, 1,
  '[{"key":"correctness","label":"Correctness"},{"key":"reasoning","label":"Reasoning"},{"key":"communication","label":"Explanation"}]'::jsonb,
  '{"1":"Novice","2":"Competent","3":"Proficient"}'::jsonb
FROM skills s WHERE s.slug IS NOT NULL
ON CONFLICT (skill_id, version_no) DO NOTHING;
